input.command:
wc -l ~/.api_key.sh; awk '{
  line=$0
  # redact anything that looks like a key/token/secret value
  gsub(/[=:][[:space:]]*["'\''"]?[^"'\''[:space:]]{8,}["'\'']?/, "=***")
  # show structure only: first word / export name
  if (match(line, /^(export[[:space:]]+)?[A-Za-z_][A-Za-z0-9_]*/)) {
    print NR": " substr(line, RSTART, RLENGTH) " ..."
  } else if (line ~ /^[[:space:]]*#/ || line ~ /^[[:space:]]*$/) {
    print NR": (comment/blank)"
  } else {
    print NR": (other)"
  }
}' ~/.api_key.sh
